import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function Cadastrar() {
  const [form, setForm] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
    foto: null,
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    setForm((prev) => ({ ...prev, foto: e.target.files[0] }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    for (const key in form) {
      formData.append(key, form[key]);
    }

    try {
      await axios.post("http://localhost:3001/usuarios", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      alert("Usuário cadastrado com sucesso!");
      navigate("/usuarios");
    } catch (erro) {
      console.error("Erro ao cadastrar:", erro);
      alert("Erro ao cadastrar usuário.");
    }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>Cadastrar Novo Usuário</h2>
      <form onSubmit={handleSubmit} style={styles.form}>
        <input style={styles.input} type="text" name="nome" placeholder="Nome completo" value={form.nome} onChange={handleChange} required />
        <input style={styles.input} type="number" name="idade" placeholder="Idade" value={form.idade} onChange={handleChange} required />
        <input style={styles.input} type="text" name="rua" placeholder="Rua" value={form.rua} onChange={handleChange} required />
        <input style={styles.input} type="text" name="bairro" placeholder="Bairro" value={form.bairro} onChange={handleChange} required />
        <input style={styles.input} type="text" name="estado" placeholder="Estado" value={form.estado} onChange={handleChange} required />
        <textarea style={styles.textarea} name="biografia" placeholder="Biografia" value={form.biografia} onChange={handleChange}></textarea>
        <input style={styles.file} type="file" name="foto" accept="image/*" onChange={handleFileChange} required />
        <button type="submit" style={styles.button}>Cadastrar</button>
      </form>
    </div>
  );
}

const styles = {
  container: {
    maxWidth: 500,
    margin: "0 auto",
    padding: "20px",
    textAlign: "center",
  },
  title: {
    marginBottom: 20,
    color: "#333",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  },
  input: {
    padding: "10px",
    borderRadius: "5px",
    border: "1px solid #ccc",
    fontSize: "16px",
  },
  textarea: {
    padding: "10px",
    borderRadius: "5px",
    border: "1px solid #ccc",
    fontSize: "16px",
    resize: "vertical",
    minHeight: "80px",
  },
  file: {
    border: "none",
    fontSize: "16px",
  },
  button: {
    backgroundColor: "#28a745",
    color: "#fff",
    padding: "10px",
    fontSize: "16px",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  }
};
